package com.example.bookingserviceproject.model;

import jakarta.persistence.MappedSuperclass;
import jakarta.persistence.PostLoad;
import jakarta.persistence.PostPersist;
import jakarta.persistence.Transient;
import org.springframework.data.domain.Persistable;

import java.util.UUID;

/**
 * Base class for entities whose id is assigned by us, not generated by the
 * database (e.g. the cart's bookingId, inventory's itemId).
 * <p>
 * Without it, {@code save()} sees an id that is already set, looks the row up,
 * and <b>updates</b> it if it exists. With it, a new entity is always inserted,
 * so a duplicate id is refused on the primary key instead of silently
 * overwriting the existing row. Once saved or loaded, the entity counts as
 * existing, so later changes (e.g. check-in) are saved as updates.
 */
@MappedSuperclass
public abstract class AssignedIdEntity implements Persistable<UUID> {

    @Transient
    private boolean isNew = true;

    /**
     * @return true until the entity has been saved or loaded from the database
     */
    @Override
    public boolean isNew(){
        return isNew;
    }

    /**
     * Marks the entity as existing, after it was saved or loaded.
     */
    @PostPersist
    @PostLoad
    void markNotNew(){
        this.isNew = false;
    }
}
